import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.model_selection import StratifiedKFold
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Check if any feature shows significant association with outcome
    significant_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('copy_number', 'expression'):
            # Welch's t-test for mean difference
            y0 = feats.x[feats.y == 0, i]
            y1 = feats.x[feats.y == 1, i]
            t_stat, _ = stats.ttest_ind(y0, y1, equal_var=False)
            if abs(t_stat) > 3.0:
                significant_features.append((fid, abs(t_stat)))

    # Sort by significance
    significant_features.sort(key=lambda x: x[1], reverse=True)

    # Check for near-duplicates (correlation >= 0.6)
    correlated_pairs = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            corr = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
            if abs(corr) >= 0.6:
                fid1, fid2 = feats.ids[i], feats.ids[j]
                # Normalize pair order to avoid duplicates
                pair = tuple(sorted([fid1, fid2]))
                correlated_pairs.add(pair)

    # Remove near-duplicates, keeping only first occurrence
    unique_features = []
    seen = set()
    for fid, _ in significant_features:
        # Check if this feature is correlated with any already selected
        is_correlated = False
        for pair in correlated_pairs:
            if fid in pair and any(f in seen for f in pair):
                is_correlated = True
                break
        if not is_correlated:
            unique_features.append(fid)
            seen.add(fid)
            if len(unique_features) >= MAX_DRIVERS:
                break

    # If we have no significant features, return empty drivers
    if not unique_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top features for regression
    selected_columns = tuple(unique_features[:MAX_DRIVERS])

    # Try to find interaction terms
    products = []
    for i, a in enumerate(selected_columns):
        for b in selected_columns[i+1:]:
            # Add interaction term if both features are present
            products.append((a, b))

    # Return design with selected features
    return Design(
        drivers=tuple(unique_features[:MAX_DRIVERS]),
        columns=selected_columns,
        products=tuple(products),
        loadings={fid: 1.0 for fid in selected_columns}
    )

